fn negate37(label:&str,v:&[Series],base:&[Series],d:&[Series],table:&[[u8;32];32],out:&mut impl Write)->Vec<Series>{let ds=series_basis36(d);let middle=quotient36(&format!("{label}-middle"),v,&ds,base,68,table,out);flip36(&format!("{label}-flip"),v,&middle,table,out,196)}
fn add37(label:&str,v:&[Series],base:&[Series],d:&[Series],e:&[Series],table:&[[u8;32];32],out:&mut impl Write)->Vec<Series>{let af=addflip36(&format!("{label}-addflip"),v,d,e,table,out);negate37(&format!("{label}-negate"),v,base,&af,table,out)}
fn same37(label:&str,v:&[Series],d:&[Series],e:&[Series],table:&[[u8;32];32],out:&mut impl Write)->bool{let target=product_space36(&d[0],e,table);assert_eq!(target.basis.len(),196);let w=quotient36(label,v,&target,d,usize::MAX,table,out);assert!(w.len()<=1);println!("SIGNED37_EQUALITY label={label} witness_dimension={} equivalent={}",w.len(),!w.is_empty());!w.is_empty()}
fn save37(dir:&str,label:&str,values:&[Series]){let mut file=BufWriter::new(fs::File::create(format!("{dir}/{label}-basis.txt")).unwrap());for (i,val) in values.iter().enumerate(){write!(file,"{}",i+1).unwrap();for x in val{write!(file," {x}").unwrap();}writeln!(file).unwrap();}file.flush().unwrap();}
fn main(){let args:Vec<String>=env::args().collect();assert_eq!(args.len(),5);let spaces=read(&args[1]);let v=&spaces[2];let base=&spaces[0];let zero=&spaces[1];let mut table=[[0u8;32];32];for a in 0..32{for b in 0..32{table[a][b]=field(a as u8,b as u8);assert_eq!(table[a][b],field_independent(a as u8,b as u8));}}
 let text=fs::read_to_string(&args[3]).unwrap();let weights=[4i32,1,-1,1,-1,-4,-1,1,-1,1];let mut d=vec![];let mut labels=vec![];
 for line in text.lines(){let p:Vec<_>=line.split_whitespace().collect();assert_eq!(p.len(),4);let step:usize=p[0].parse().unwrap();assert_eq!(step,d.len());assert!(step<10);assert_eq!(p[3].parse::<i32>().unwrap(),weights[step]);assert!(p[2].parse::<usize>().unwrap()<83);assert!(!labels.contains(&p[1].to_string()));let path=format!("{}/coupled-{}-basis.txt",args[2],p[1]);let values=read_basis36(&path);series_basis36(&values);d.push(values);labels.push(p[1].to_string());println!("SIGNED37_INPUT step={step} label={} weight={} rank=196",p[1],weights[step]);}assert_eq!(d.len(),10);assert_eq!(weights.iter().sum::<i32>(),0);
 fs::create_dir(&args[4]).unwrap();let mut out=BufWriter::new(fs::File::create(format!("{}/signed-certificates.txt",args[4])).unwrap());
 // Expression one: positive total minus negative total, actual deck order.
 let d02=add37("positive-double2",v,base,&d[0],&d[0],&table,&mut out);let d04=add37("positive-double4",v,base,&d02,&d02,&table,&mut out);let mut positive=d04;
 for k in [1usize,3,7,9]{positive=add37(&format!("positive-add-{k}"),v,base,&positive,&d[k],&table,&mut out);}
 let d52=add37("negative-double2",v,base,&d[5],&d[5],&table,&mut out);let d54=add37("negative-double4",v,base,&d52,&d52,&table,&mut out);let mut negative=d54;
 for k in [2usize,4,6,8]{negative=add37(&format!("negative-add-{k}"),v,base,&negative,&d[k],&table,&mut out);}
 save37(&args[4],"positive",&positive);save37(&args[4],"negative",&negative);
 let totals_equal=same37("positive-versus-negative",v,&positive,&negative,&table,&mut out);
 let minus_negative=negate37("minus-negative-total",v,base,&negative,&table,&mut out);let first=add37("signed-difference",v,base,&positive,&minus_negative,&table,&mut out);save37(&args[4],"signed-first",&first);
 let first_zero=same37("signed-first-versus-zero",v,&first,zero,&table,&mut out);assert_eq!(totals_equal,first_zero);
 // Independently ordered expression:4(D0-D5)+(D1-D6)-(D2-D7)+(D3-D8)-(D4-D9).
 let mut differences=vec![];for k in 0..5{let minus=negate37(&format!("paired-negate-{k}"),v,base,&d[k+5],&table,&mut out);let diff=add37(&format!("paired-difference-{k}"),v,base,&d[k],&minus,&table,&mut out);save37(&args[4],&format!("paired-{k}"),&diff);differences.push(diff);}
 let pair2=add37("paired-double2",v,base,&differences[0],&differences[0],&table,&mut out);let mut second=add37("paired-double4",v,base,&pair2,&pair2,&table,&mut out);
 for k in 1..5{let term=if k%2==0{negate37(&format!("paired-term-negate-{k}"),v,base,&differences[k],&table,&mut out)}else{differences[k].clone()};second=add37(&format!("paired-sum-{k}"),v,base,&second,&term,&table,&mut out);}
 save37(&args[4],"signed-second",&second);assert!(same37("independent-expression-equality",v,&first,&second,&table,&mut out));let second_zero=same37("signed-second-versus-zero",v,&second,zero,&table,&mut out);assert_eq!(first_zero,second_zero);out.flush().unwrap();
 let result=format!("principal={first_zero}\nindependent_expression_equal=true\npositive_negative_equal={totals_equal}\n");fs::write(format!("{}/signed-result.txt",args[4]),result).unwrap();println!("SIGNED37_RESULT actual_deck_labels=10 signed_class_principal={first_zero} positive_negative_equal={totals_equal} independent_expression_equal=true all_generator_memberships=checked independent_products=all target_factor_evaluated=false");println!("SIGNED37_ALL_CHECKS_PASS");}
